/* Game Hard Mode for every lesson after French lesson 1: the lesson's Hard Mode test (cloze text and listening) becomes a
   row of mini-games – a warm-up game that fits the topic, a string game, a word train, magic gaps and a radio quiz with all
   recordings on one page. Completing every game unlocks the lesson's arcade. The previous test stays available. */
(() => {
'use strict';
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shuffle=xs=>{const a=[...xs];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const norm=s=>String(s??'').normalize('NFC').trim().toLowerCase();
const calm=()=>!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
const COURSES={
 fr:{content:()=>window.FR_A1_HARD_CONTENT,mode:()=>window.FR_A1_HARD_MODE,audio:()=>window.FR_A1_HARD_AUDIO,target:'fr',meaning:'de',lessons:'frLessons',voice:'fr-FR',ui:'de',first:window.A1_APP_META?.course==='francais-a2'?1:2,accents:['é','è','ê','à','ç','’','î','ô','û']},
 de:{content:()=>window.DE_A1_HARD_CONTENT,mode:()=>window.DE_A1_HARD_MODE,audio:()=>window.DE_A1_HARD_AUDIO,target:'de',meaning:'fr',lessons:'deLessons',voice:'de-DE',ui:'fr',first:1,accents:['ä','ö','ü','ß','Ä','Ö','Ü']}
};
let course='fr';
const C=()=>COURSES[course];
const en=()=>window.A1Profile?.getUiLang?.()==='en';
// Interface text: German for the French course, French for the German course, English when chosen.
const T=(de,english,fr)=>en()?english:C().ui==='fr'?fr:de;
const LEARN=new Set(['memory','numbers','spell','clock']);
const GAMES={
 memory:{icon:'🃏',name:()=>T('Karten-Memory','Card memory','Memory des cartes'),rule:()=>T('Decke Paare auf: Wort und Bedeutung gehören zusammen.','Flip pairs: word and meaning belong together.','Retourne des paires : le mot et son sens vont ensemble.')},
 numbers:{icon:'🔐',name:()=>T('Zahlen-Tresor','Number safe','Le coffre aux nombres'),rule:()=>T('Hör die Zahl und tipp sie in den Tresor – dann springt er auf.','Listen to the number and key it into the safe – then it opens.','Écoute le nombre et tape-le sur le coffre – il s’ouvre.')},
 spell:{icon:'🔤',name:()=>T('Buchstabier-Box','Spelling box','La boîte à lettres'),rule:()=>T('Hör, wie das Wort buchstabiert wird, und setz die Buchstaben zusammen.','Listen to the word being spelled and put the letters together.','Écoute le mot épelé et assemble les lettres.')},
 clock:{icon:'⏰',name:()=>T('Uhr-Stellen','Clock game','L’horloge'),rule:()=>T('Lies die Uhr und tipp die passende Uhrzeit an.','Read the clock and tap the matching time.','Lis l’horloge et choisis l’heure qui correspond.')},
 match:{icon:'🧵',name:()=>T('Fadenspiel','String game','Le jeu des fils'),rule:()=>T('Spanne Fäden zwischen Hinweis und passender Form.','Stretch strings between each clue and its form.','Relie chaque indice à la bonne forme.')},
 order:{icon:'🚂',name:()=>T('Wörter-Zug','Word train','Le train des mots'),rule:()=>T('Hänge die richtigen Waggons an die Lok. Ein paar gehören nicht dazu!','Hook the right wagons to the engine. Some do not belong!','Accroche les bons wagons à la locomotive. Certains sont en trop !')},
 text:{icon:'🪄',name:()=>T('Zauber-Lücken','Magic gaps','Les trous magiques'),rule:()=>T('Fülle die leuchtenden Lücken und repariere die Sätze.','Fill the glowing gaps and repair the sentences.','Remplis les trous lumineux et répare les phrases.')},
 listening:{icon:'🎧',name:()=>T('Radio-Quiz','Radio quiz','Le quiz radio'),rule:()=>T('Hör jedes Gespräch höchstens zweimal und beantworte die Fragen.','Listen to each recording at most twice and answer the questions.','Écoute chaque enregistrement deux fois au maximum et réponds.')}
};
const SPECIAL={fr:{2:'spell',3:'numbers',4:'clock'},de:{2:'spell',3:'numbers',4:'clock'}};
const cheers={fr:['Bravo !','Super !','Génial !','Parfait !'],de:['Super!','Klasse!','Prima!','Genau!']};

/* ---------- Words for the special games ---------- */
const FR_UNITS=['zéro','un','deux','trois','quatre','cinq','six','sept','huit','neuf','dix','onze','douze','treize','quatorze','quinze','seize'];
const FR_TENS={20:'vingt',30:'trente',40:'quarante',50:'cinquante',60:'soixante'};
function numberFr(n){if(n<=16)return FR_UNITS[n];if(n<20)return 'dix-'+FR_UNITS[n-10];if(n===100)return 'cent';
 if(n<70){const t=Math.floor(n/10)*10,u=n%10;return FR_TENS[t]+(u===0?'':u===1?' et un':'-'+FR_UNITS[u]);}
 if(n<80)return n===71?'soixante et onze':'soixante-'+numberFr(n-60);
 if(n===80)return 'quatre-vingts';return 'quatre-vingt-'+numberFr(n-80);}
const DE_UNITS=['null','eins','zwei','drei','vier','fünf','sechs','sieben','acht','neun','zehn','elf','zwölf','dreizehn','vierzehn','fünfzehn','sechzehn','siebzehn','achtzehn','neunzehn'];
const DE_TENS={20:'zwanzig',30:'dreißig',40:'vierzig',50:'fünfzig',60:'sechzig',70:'siebzig',80:'achtzig',90:'neunzig'};
function numberDe(n){if(n<20)return DE_UNITS[n];if(n===100)return 'hundert';const t=Math.floor(n/10)*10,u=n%10;return u===0?DE_TENS[t]:(u===1?'ein':DE_UNITS[u])+'und'+DE_TENS[t];}
const NUMBERS={fr:[16,17,21,30,41,57,66,70,71,75,80,81,90,96,99,100],de:[13,16,17,21,30,32,45,57,60,66,71,77,89,93,99,100]};
const SPELL={fr:['LÉA','MARTIN','HUGO','CHLOÉ','DUPONT','NANTES','ZOÉ','FRANÇOIS','BERNARD','LYON'],de:['MEIER','ANNA','MÜLLER','JÜRGEN','SCHULZ','KÖLN','LENA','BÄCKER','ZIEGLER','WAGNER']};
const DECOYS={fr:'ABCDEFGHILMNOPRSTUVÉÈ',de:'ABCDEFGHIKLMNOPRSTUWZÄÖÜ'};
const FR_HOURS=['','une','deux','trois','quatre','cinq','six','sept','huit','neuf','dix','onze','douze'];
const DE_HOURS=['','eins','zwei','drei','vier','fünf','sechs','sieben','acht','neun','zehn','elf','zwölf'];
function timeFr(h,m){const next=h%12+1,hours=x=>x===1?'une heure':FR_HOURS[x]+' heures';return 'Il est '+(m===0?hours(h):m===15?hours(h)+' et quart':m===30?hours(h)+' et demie':hours(next)+' moins le quart')+'.';}
function timeDe(h,m){const next=h%12+1;return 'Es ist '+(m===0?(h===1?'ein':DE_HOURS[h])+' Uhr':m===15?'Viertel nach '+DE_HOURS[h]:m===30?'halb '+DE_HOURS[next]:'Viertel vor '+DE_HOURS[next])+'.';}

/* ---------- Building the games from the lesson's Hard Mode content ---------- */
const supports=(courseKey,id)=>{const cfg=COURSES[courseKey];return !!cfg&&Number(id)>=cfg.first&&!!cfg.content()?.[id];};
function sentencesOf(text){const safe=String(text).replace(/(\d)\.(\s)/g,'$1․$2');return (safe.match(/[^.!?\n]+[.!?]*/g)||[]).map(s=>s.trim().replace(/․/g,'.')).filter(s=>/\S/.test(s)&&!/^[.!?]+$/.test(s));}
const fill=(sentence,data,keep=-1)=>sentence.replace(/\{\{(\d+)\}\}/g,(_,n)=>Number(n)===keep?'___':data.gaps[Number(n)]?.answers?.[0]??'');
const gapIds=s=>[...String(s).matchAll(/\{\{(\d+)\}\}/g)].map(m=>Number(m[1]));
function distance(a,b){a=norm(a);b=norm(b);const d=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let p=d[0];d[0]=i;for(let j=1;j<=b.length;j++){const t=d[j];d[j]=Math.min(d[j]+1,d[j-1]+1,p+(a[i-1]===b[j-1]?0:1));p=t;}}return d[b.length];}
const concept=h=>norm(String(h||'').split(/[:,(]/)[0]);
function vocabulary(courseKey,id){const cfg=COURSES[courseKey],V=window.A1_VOCABULARY_CONTENT||[],seenT=new Set(),seenM=new Set(),out=[];
 for(const v of V){if(!(v[cfg.lessons]||[]).includes(Number(id)))continue;const t=String(v[cfg.target]||'').trim(),m=String(v[cfg.meaning]||'').trim();if(!t||!m||t.length>26||m.length>30||/[()…]/.test(t+m)||seenT.has(norm(t))||seenM.has(norm(m)))continue;seenT.add(norm(t));seenM.add(norm(m));out.push([t,m]);}
 return out;}
function special(courseKey,id){const kind=SPECIAL[courseKey]?.[Number(id)];
 if(kind==='numbers'){const rounds=shuffle(NUMBERS[courseKey]).slice(0,6).map(n=>({n,word:courseKey==='fr'?numberFr(n):numberDe(n)}));return {type:'numbers',rounds,title:['Zahlen hören und eintippen','Hear and key in numbers','Écouter et taper les nombres'],skills:['nombres']};}
 if(kind==='spell'){const rounds=shuffle(SPELL[courseKey]).slice(0,5).map(word=>{const letters=[...word],decoys=shuffle([...DECOYS[courseKey]].filter(c=>!letters.includes(c))).slice(0,3);return {word,tiles:shuffle([...letters,...decoys])};});return {type:'spell',rounds,title:['Namen buchstabieren','Spell names','Épeler des noms'],skills:['alphabet']};}
 if(kind==='clock'){const used=new Set(),rounds=[];while(rounds.length<6){const h=1+Math.floor(Math.random()*12),m=[0,15,30,45][Math.floor(Math.random()*4)];if(used.has(h+':'+m))continue;used.add(h+':'+m);const say=courseKey==='fr'?timeFr:timeDe;rounds.push({h,m,answer:say(h,m),options:shuffle([0,15,30,45].map(x=>say(h,x)))});}return {type:'clock',rounds,title:['Wie spät ist es?','What time is it?','Quelle heure est-il ?'],skills:['heure']};}
 const pairs=shuffle(vocabulary(courseKey,id)).slice(0,6);return pairs.length>=4?{type:'memory',pairs,title:['Vokabel-Memory','Vocabulary memory','Memory du vocabulaire'],skills:['vocabulaire']}:null;}
function build(courseKey,id){course=courseKey;const data=COURSES[courseKey].content()[id],tasks=[],pages=[];
 const warm=special(courseKey,id);if(warm){pages.push({key:warm.type,ids:[tasks.length]});tasks.push(warm);}
 const sentences=sentencesOf(data.text),used=new Set();
 // Word train: two short sentences with one gap; the extra wagons are look-alike forms from the same text.
 const answersOf=n=>data.gaps[n].answers[0];
 const trains=shuffle(sentences.filter(s=>{const g=gapIds(s),words=fill(s,data).split(/\s+/).length;return g.length===1&&words>=4&&words<=9&&!/\s/.test(answersOf(g[0]));})).slice(0,2);
 const orderIds=[];for(const s of trains){const n=gapIds(s)[0],right=answersOf(n),tokens=fill(s,data).split(/\s+/).reduce((out,w)=>{if(/^[?!:;»]$/.test(w)&&out.length)out[out.length-1]+=' '+w;else out.push(w);return out;},[]);
  const others=[...new Set(data.gaps.map(g=>g.answers[0]).filter(x=>norm(x)!==norm(right)&&!/\s/.test(x)&&!tokens.map(norm).includes(norm(x))))].sort((x,y)=>(concept(data.gaps.find(g=>g.answers[0]===y).hint)===concept(data.gaps[n].hint))-(concept(data.gaps.find(g=>g.answers[0]===x).hint)===concept(data.gaps[n].hint))||distance(x,right)-distance(y,right));
  const extras=others.slice(0,2);if(extras.length<1)continue;used.add(n);orderIds.push(tasks.length);tasks.push({type:'order',tokens:[...tokens,...extras],required:tokens.length,answer:tokens.join(' '),gaps:[n],title:['Satz bauen','Build the sentence','Construis la phrase'],skills:[data.gaps[n].hint].filter(Boolean)});}
 // String game: five clues with different answers.
 const matchGaps=[],seenA=new Set(),seenH=new Set();for(const n of shuffle(data.gaps.map((_,i)=>i))){if(used.has(n))continue;const g=data.gaps[n],a=norm(g.answers[0]),h=norm(g.hint);if(!h||seenA.has(a)||seenH.has(h))continue;seenA.add(a);seenH.add(h);matchGaps.push(n);if(matchGaps.length===5)break;}
 let matchId=null;if(matchGaps.length>=3){matchGaps.sort((x,y)=>x-y);matchGaps.forEach(n=>used.add(n));matchId=tasks.length;tasks.push({type:'match',labels:matchGaps.map(n=>data.gaps[n].hint),answers:matchGaps.map(n=>data.gaps[n].answers[0]),gaps:matchGaps,policy:matchGaps.map(n=>({strictAccents:!!data.gaps[n].strictAccents})),title:['Hinweis und Form verbinden','Connect clue and form','Relie indice et forme'],skills:[]});}
 if(matchId!==null)pages.push({key:'match',ids:[matchId]});
 if(orderIds.length)pages.push({key:'order',ids:orderIds});
 // Magic gaps: every remaining gap of the test, in its own sentence.
 const textIds=[];data.gaps.forEach((g,n)=>{if(used.has(n))return;const s=sentences.find(x=>gapIds(x).includes(n));if(!s)return;textIds.push(tasks.length);tasks.push({type:'text',sentence:fill(s,data,n),hint:g.hint||'',answers:g.answers,policy:{strictAccents:!!g.strictAccents},gaps:[n],title:['Lücke füllen','Fill the gap','Complète le trou'],skills:[g.hint].filter(Boolean)});});
 for(let k=0;k<textIds.length;k+=5)pages.push({key:'text',ids:textIds.slice(k,k+5)});
 // Radio quiz: all recordings on one page.
 const listenIds=[];(data.listening||[]).forEach((block,b)=>block.questions.forEach(q=>{listenIds.push(tasks.length);tasks.push(q.options?{type:'choice',block:b,q:q.q,options:q.options,answers:q.answers,title:[q.q],skills:q.skills||[]}:{type:'listen-text',block:b,q:q.q,answers:q.answers,policy:{format:q.format,strictAccents:!!q.strictAccents},title:[q.q],skills:q.skills||[]});}));
 if(listenIds.length)pages.push({key:'listening',ids:listenIds,blocks:(data.listening||[]).map((_,b)=>b)});
 return {tasks,pages,version:data.version};}

/* ---------- Entry on the lesson page ---------- */
const lockIcon=open=>`<svg class="hard-lock-icon" viewBox="0 0 24 24" fill="none" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0${open?'':'v3'}"/><path d="M12 14v3"/></svg>`;
const done=a=>a?.kind==='hard-games'&&a.phase==='reviewed'&&!!a.completedAt;
function entryHtml({course:courseKey,lesson,state,unlocked}){course=courseKey;const g=state.lessonWork?.[lesson.id]?.hardMode?.games,a=g?.attempt;const warm=SPECIAL[courseKey]?.[lesson.id]||'memory';
 const label=unlocked?(a?(done(a)?T('Ansehen','Review','Voir'):T('Fortsetzen','Resume','Continuer')):T('Starten','Start','Commencer')):T('Gesperrt','Locked','Verrouillé');
 return `<section class="hard-entry ${unlocked?'is-unlocked':'is-locked'}" data-i18n-ignore aria-label="Hard Mode"><button type="button" class="hard-entry-button" data-hard-start ${unlocked?'':'disabled'}>${lockIcon(unlocked)}<strong>Hard Mode</strong><span>${label}${unlocked?' →':''}</span></button><p class="hard-entry-hint">${unlocked?[warm,'match','order','text','listening'].map(k=>GAMES[k].icon+' '+GAMES[k].name()).join(' · ')+' · 🕹️ '+T('Spielhalle als Belohnung','Arcade as a reward','Salle de jeux en récompense'):T('Ab 80 % im Lektionscheck','Unlocks at 80% in the lesson check','Dès 80 % au bilan de la leçon')}</p></section>`;}

/* ---------- The game Hard Mode ---------- */
let redraw=null;
window.addEventListener('a1suite:languagechange',()=>redraw?.());
function render({course:courseKey,lesson,view,state,save,onBack,onLegacy}){
 course=courseKey;const cfg=C(),id=Number(lesson.id),mode=cfg.mode();
 const hard=((state.lessonWork||={})[id]||={}).hardMode||={},p=hard.games||={history:[]};p.history||=[];p.arcade||={best:{},stars:{}};
 let a=p.attempt,root=null,playing=null,run=0,timer=null,error='',notice='',storageError='',arcadeView=null,stopGame=null,memoryDismiss=null,resize=null;
 const tasks=()=>a.content.tasks,pages=()=>a.content.pages;
 const persist=(complete=false)=>{try{save(complete);storageError='';}catch{storageError=T('Speichern fehlgeschlagen. Lass diese Seite offen.','Saving failed. Keep this page open.','Échec de l’enregistrement. Garde cette page ouverte.');}const el=root?.querySelector('[data-games-save]');if(el)el.textContent=storageError||T('Zwischenstand gespeichert','Progress saved','Progression enregistrée');};
 const matches=(v,answers,policy={})=>mode?.matches?mode.matches(v,answers,policy):answers.some(x=>norm(x)===norm(v));
 const arcadeOpen=()=>!!window.FR_A1_ARCADE?.lessonGames&&(!!p.arcadeUnlocked||done(a)||p.history.some(done));
 function cancel(){run++;if(timer)clearTimeout(timer);timer=null;playing=null;window.A1Voice?.cancel?.();}
 function cleanup(){stopGame?.();stopGame=null;if(memoryDismiss)document.removeEventListener('click',memoryDismiss,true);memoryDismiss=null;if(resize)window.removeEventListener('resize',resize);resize=null;}
 function leave(){cleanup();cancel();redraw=null;onBack();}
 function speak(text){try{window.A1Voice?.speak?.(text,{lang:cfg.voice,rate:.85});}catch{}}
 function confetti(target,count=18){if(!target||calm())return;const box=document.createElement('div');box.className='game-confetti';box.setAttribute('aria-hidden','true');const colors=['#ff5d8f','#ffd166','#06d6a0','#4cc9f0','#b388ff','#ff9f1c'];for(let n=0;n<count;n++){const i=document.createElement('i');i.style.cssText=`left:${Math.random()*100}%;background:${colors[n%colors.length]};animation-delay:${Math.random()*.25}s;transform:rotate(${Math.random()*360}deg)`;box.append(i);}target.append(box);setTimeout(()=>box.remove(),1600);}
 function mount(body){cleanup();view.innerHTML=`<div class="hard-mode lesson-challenge hard-pilot game-hard" data-i18n-ignore data-bug-lesson="${id}"><div class="between"><button class="tiny-btn" data-games-back>← ${T('Zur Lektion','Back to lesson','Retour à la leçon')}</button><span class="hard-eyebrow">HARD MODE · ${id}</span></div><h2 data-games-heading tabindex="-1">${T('Lektions-Challenge','Lesson challenge','Défi de la leçon')}</h2>${a&&!done(a)?`<p data-games-save class="hard-save-status" role="status">${E(storageError)||T('Zwischenstand gespeichert','Progress saved','Progression enregistrée')}</p><div class="game-restart" data-games-restart-box><button type="button" class="tiny-btn" data-games-restart>↺ ${T('Hard Mode neu starten','Restart Hard Mode','Recommencer le Hard Mode')}</button></div>`:''}${body}</div>`;
  root=view.firstElementChild;root.querySelector('[data-games-back]').onclick=leave;
  root.querySelectorAll('[data-games-arcade]').forEach(el=>el.onclick=()=>{cancel();arcadeView='hub';draw();window.scrollTo?.({top:0,behavior:'instant'});});
  root.querySelector('[data-games-legacy]')?.addEventListener('click',()=>{cleanup();cancel();redraw=null;onLegacy?.();});
  root.querySelector('[data-games-restart]')?.addEventListener('click',()=>{const box=root.querySelector('[data-games-restart-box]');box.innerHTML=`<p>${T('Von vorn beginnen? Dein bisheriger Versuch bleibt gespeichert.','Start again? Your current attempt stays saved.','Recommencer ? Ta tentative actuelle reste enregistrée.')}</p><div class="game-restart-actions"><button type="button" class="hard-start" data-games-confirm-restart>${T('Neu starten','Restart','Recommencer')}</button><button type="button" class="secondary-btn" data-games-cancel-restart>${T('Abbrechen','Cancel','Annuler')}</button></div>`;box.querySelector('[data-games-confirm-restart]').onclick=start;box.querySelector('[data-games-cancel-restart]').onclick=draw;});}
 function start(){cancel();if(a)p.history.push(JSON.parse(JSON.stringify(a)));const content=build(courseKey,id);a=p.attempt={version:1,kind:'hard-games',content,phase:'running',page:0,round:0,retryIds:[],
  answers:content.tasks.map(q=>q.type==='match'?q.labels.map(()=>''):q.type==='order'||LEARN.has(q.type)?[]:''),checked:content.tasks.map(()=>false),solved:content.tasks.map(()=>false),firstCorrect:content.tasks.map(()=>null),hints:content.tasks.map(()=>false),
  orders:content.tasks.map(q=>q.type==='match'?shuffle(q.answers):q.type==='order'?shuffle(q.tokens.map((_,n)=>n)):q.type==='choice'?shuffle(q.options):null),game:{},plays:(cfg.content()[id].listening||[]).map(()=>0),rate:.75,startedAt:Date.now()};persist();draw();focusTop();}
 function focusTop(){root?.querySelector('[data-games-heading]')?.focus?.({preventScroll:true});window.scrollTo?.({top:0,behavior:'instant'});}
 const scored=i=>!LEARN.has(tasks()[i].type);
 const gameOf=page=>GAMES[page.key]||GAMES.text;
 function progress(){const all=pages().flatMap(pg=>pg.ids),n=a.solved.filter(Boolean).length;return `<div class="challenge-progress game-progress"><span><b class="game-stars" aria-hidden="true">⭐ ${n}</b> ${n}/${all.length} ${T('geschafft','done','réussis')}</span><div role="progressbar" style="--pilot-total:${all.length}" aria-label="${T('Geschaffte Aufgaben','Completed tasks','Exercices réussis')}" aria-valuenow="${n}" aria-valuemin="0" aria-valuemax="${all.length}">${all.map(i=>`<i class="${a.solved[i]?'is-done':''}"></i>`).join('')}</div></div>`;}
 function nav(){const extra=arcadeOpen();return `<nav class="pilot-scenes game-nav" style="--pilot-pages:${pages().length+(extra?1:0)}" aria-label="${T('Seiten','Pages','Pages')}">${pages().map((pg,n)=>{const ok=pg.ids.every(i=>a.solved[i]),g=gameOf(pg);return `<button type="button" data-games-goto="${n}" class="game-${pg.key} ${ok?'is-done':''}" aria-label="${T('Seite','Page','Page')} ${n+1}: ${E(g.name())}${ok?' ✓':''}" ${n===a.page?'aria-current="step"':''}><i aria-hidden="true">${ok?'✅':g.icon}</i>${n+1}</button>`;}).join('')}${extra?`<button type="button" data-games-arcade class="game-arcade" aria-label="${T('Spielhalle','Arcade','Salle de jeux')}"><i aria-hidden="true">🕹️</i>${T('Spiele','Games','Jeux')}</button>`:''}</nav>`;}
 function intro(){const content=a?.content||build(courseKey,id);mount(`<section class="card hard-intro game-intro"><span class="hard-eyebrow">${T('HARD MODE ALS SPIELWELT','HARD MODE AS A GAME WORLD','LE HARD MODE EN JEUX')}</span><h3>${T(`Deine Spielwelt: ${content.pages.length} Mini-Spiele`,`Your game world: ${content.pages.length} mini-games`,`Ton monde de jeux : ${content.pages.length} mini-jeux`)}</h3><p>${T('Alles aus dem Hard-Mode-Test dieser Lektion – als Spiele. Schaffst du alle, schaltest du die Spielhalle frei.','Everything from this lesson’s Hard Mode test – as games. Finish them all to unlock the arcade.','Tout le test Hard Mode de cette leçon – en jeux. Réussis-les tous pour débloquer la salle de jeux.')}</p><ol class="game-map">${content.pages.map((pg,n)=>{const g=gameOf(pg);return `<li class="game-tile game-${pg.key}"><button type="button" data-games-start-at="${n}"><span class="game-icon" aria-hidden="true">${g.icon}</span><strong>${n+1}. ${E(g.name())}</strong><small>${pg.ids.length} ${pg.ids.length===1?T('Spiel','game','jeu'):T('Runden','rounds','manches')}</small></button></li>`;}).join('')}</ol>${arcadeOpen()?`<button type="button" class="arcade-entry" data-games-arcade>🕹️ ${T('Spielhalle','Arcade','Salle de jeux')} →</button>`:''}<p>${T('Ohne Zeitlimit. Hinweise sind freiwillig. Was beim ersten Prüfen nicht klappt, übst du am Ende gezielt.','No time limit. Hints are optional. Whatever is wrong at the first check comes back at the end.','Sans limite de temps. Les indices sont facultatifs. Ce qui est faux au premier essai revient à la fin.')}</p><button class="hard-start" data-games-begin>${a?T('Weiterspielen','Continue','Continuer'):T('Los geht’s','Let’s go','C’est parti')} →</button><div class="hard-links"><button class="tiny-btn" data-games-legacy>${T('Bisherigen Hard-Mode-Test öffnen','Open the previous Hard Mode test','Ouvrir l’ancien test Hard Mode')}</button></div></section>`);
  root.querySelector('[data-games-begin]').onclick=()=>a?(a.phase==='running'?scene():summary()):start();
  root.querySelectorAll('[data-games-start-at]').forEach(el=>el.onclick=()=>{if(!a||done(a))start();a.page=Number(el.dataset.gamesStartAt);persist();draw();focusTop();});}
 const pending=i=>a.round?a.retryIds.includes(i)&&!a.checked[i]:!a.checked[i];
 const visible=()=>{const all=pages()[a.page].ids,list=all.filter(i=>!a.round||a.retryIds.includes(i));return list.length?list:all;};
 function goTo(n){cancel();notice='';a.page=n;persist();draw();focusTop();}

 /* ----- task markup ----- */
 const accentKeys=i=>`<div class="game-accents" role="group" aria-label="${T('Sonderzeichen einfügen','Insert special characters','Insérer des caractères spéciaux')}">${cfg.accents.map(c=>`<button type="button" data-games-accent="${i}" data-char="${c}" lang="${cfg.target}">${c}</button>`).join('')}</div>`;
 function body(i){const q=tasks()[i],locked=a.checked[i];
  if(q.type==='memory')return `<div data-games-memory="${i}"></div>`;
  if(q.type==='numbers'||q.type==='spell'||q.type==='clock')return `<div data-games-rounds="${i}"></div>`;
  if(q.type==='match')return `<p class="pilot-connect-instructions">${T('Tippe links einen Hinweis und rechts die passende Form an.','Tap a clue on the left, then its form on the right.','Touche un indice à gauche, puis la bonne forme à droite.')}</p><div class="pilot-connect" data-games-connect="${i}" style="--match-count:${q.labels.length}"><svg class="pilot-connect-lines" aria-hidden="true" focusable="false"></svg><div class="pilot-connect-left">${q.labels.map((l,n)=>`<button type="button" data-match-left="${n}" ${locked?'disabled':''}>${E(l)}</button>`).join('')}</div><div class="pilot-connect-right">${a.orders[i].map((v,n)=>`<button type="button" data-match-right="${n}" lang="${cfg.target}" ${locked?'disabled':''}>${E(v)}</button>`).join('')}</div></div>`;
  if(q.type==='order')return `<div class="game-train ${locked&&a.solved[i]?'is-departing':''}"><span class="game-loco" aria-hidden="true">🚂</span>${a.answers[i].map((n,k)=>`<button type="button" class="game-wagon" data-games-wagon="${i}" data-pos="${k}" style="--hue:${n*67%360}" lang="${cfg.target}" ${locked?'disabled':''}>${E(q.tokens[n])}</button>`).join('')||`<span class="game-train-empty">${T('Wähle die passenden Waggons in der richtigen Reihenfolge. Einige bleiben übrig.','Choose the right wagons in the right order. Some are left over.','Choisis les bons wagons dans le bon ordre. Certains restent.')}</span>`}</div><div class="challenge-word-bank game-depot">${a.orders[i].map(n=>`<button type="button" data-pilot-token="${i}" data-games-token="${i}" data-token="${n}" style="--hue:${n*67%360}" lang="${cfg.target}" ${locked||a.answers[i].includes(n)?'disabled':''}>${E(q.tokens[n])}</button>`).join('')}<button type="button" class="game-undo" data-games-undo="${i}" ${locked?'disabled':''}>↶ ${T('Zurücknehmen','Undo','Annuler')}</button></div>`;
  if(q.type==='text'){const [before,...rest]=q.sentence.split('___');return `<div class="game-bubble"><span class="game-speaker" aria-hidden="true">${['🧑‍🎓','👩‍🏫','🧑‍🍳','👩‍🎨','🧑‍✈️'][i%5]}</span><div><label class="pilot-field game-gap-line"><span lang="${cfg.target}">${E(before)}<input type="text" class="game-gap" data-games-input="${i}" value="${E(a.answers[i])}" lang="${cfg.target}" ${locked?'readonly':''} aria-label="${E(q.hint||T('Lücke','Gap','Trou'))}" autocomplete="off" spellcheck="false" autocapitalize="off">${E(rest.join('___'))}</span></label>${q.hint?`<p class="game-gap-hint">💡 ${E(q.hint)}</p>`:''}</div></div>${locked?'':accentKeys(i)}`;}
  if(q.type==='choice')return `<fieldset class="challenge-options game-quiz" ${locked?'disabled':''}><legend class="challenge-sr">${E(q.q)}</legend>${a.orders[i].map((v,n)=>`<label class="hard-option game-quiz-card ${locked&&q.answers.includes(v)?'is-answer':''}" style="--hue:${[330,200,45,150][n%4]}"><input type="radio" name="games-${i}" data-games-choice="${i}" value="${E(v)}" ${a.answers[i]===v?'checked':''}><b class="game-letter" aria-hidden="true">${'ABCD'[n]||n+1}</b><span lang="${cfg.target}">${E(v)}</span></label>`).join('')}</fieldset>`;
  if(q.type==='listen-text')return `<label class="pilot-field game-wand">${T('Deine Antwort','Your answer','Ta réponse')}<input type="${q.policy.format==='number'?'text" inputmode="numeric':'text'}" data-games-input="${i}" value="${E(a.answers[i])}" lang="${cfg.target}" ${locked?'readonly':''} autocomplete="off" spellcheck="false" autocapitalize="off"></label>`;
  return '';}
 const shown=(q,i)=>q.type==='order'?a.answers[i].map(n=>q.tokens[n]).join(' '):Array.isArray(a.answers[i])?a.answers[i].join(' / '):a.answers[i];
 const solution=q=>q.type==='order'?q.answer:q.type==='match'?q.labels.map((l,n)=>l+' → '+q.answers[n]).join(' · '):q.type==='text'?q.sentence.replace('___',q.answers[0]):q.answers[0];
 function card(i){const q=tasks()[i],learn=LEARN.has(q.type),checked=a.checked[i];return `<section class="card pilot-task game-card game-${learn?q.type:q.type==='choice'||q.type==='listen-text'?'listening':q.type} ${checked?(a.solved[i]?'is-won':'is-retry'):''}" data-games-task="${i}"><h3 ${q.title.length===1?`lang="${cfg.target}"`:''}>${E(q.title.length===3?T(...q.title):q.title[0])}</h3>${body(i)}${checked&&!learn?`<div class="challenge-feedback ${a.solved[i]?'is-correct':'is-practice'}" role="status"><strong>${a.solved[i]?`<span class="game-cheer" lang="${cfg.target}">${cheers[course][i%4]}</span> ✓`:`<span class="game-cheer" aria-hidden="true">💪</span> ${T('Das üben wir noch einmal.','We will practise this again.','On s’entraîne encore.')}`}</strong>${a.solved[i]?'':`<p>${T('Richtig ist','The right answer is','La bonne réponse est')}: <b lang="${cfg.target}">${E(solution(q))}</b></p>`}${q.type==='text'||q.type==='order'?`<button type="button" class="tiny-btn" data-games-say="${i}">🔊 ${T('Anhören','Listen','Écouter')}</button>`:''}</div>`:''}</section>`;}
 function radio(b,n,count){const data=cfg.content()[id];return `<section class="game-radio" data-radio="${b}"><p class="hard-eyebrow">🎧 ${T('Hörtext','Recording','Enregistrement')} ${n+1}/${count}</p><div class="challenge-audio"><span class="game-eq" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></span><button class="secondary-btn" data-games-listen="${b}">▶ ${T('Anhören','Listen','Écouter')} (${a.plays[b]||0}/2)</button>${n===0?`<label>${T('Tempo','Speed','Vitesse')}<select data-games-rate><option value="0.75" ${a.rate===.75?'selected':''}>75 %</option><option value="1" ${a.rate===1?'selected':''}>100 %</option></select></label>`:''}<button class="tiny-btn" data-games-stop="${b}" ${playing!==b?'hidden':''}>${T('Stoppen · zählt als Anhören','Stop · counts as a play','Arrêter · compte comme une écoute')}</button></div></section>`;}
 function scene(){const pg=pages()[a.page],list=visible(),g=gameOf(pg),learnPage=list.every(i=>!scored(i)),checked=list.every(i=>a.checked[i]);
  let cards;if(pg.blocks){const data=cfg.content()[id];cards=pg.blocks.map((b,n)=>radio(b,n,pg.blocks.length)+list.filter(i=>tasks()[i].block===b).map(card).join('')+(pg.ids.filter(i=>tasks()[i].block===b).every(i=>a.checked[i])?`<details class="challenge-transcript"><summary>${T('Transkript ansehen','Show transcript','Voir la transcription')}</summary><p lang="${cfg.target}">${E(data.listening[b].text).replace(/\n/g,'<br>')}</p></details>`:'')).join('')+`<p class="hard-error" data-games-audio-error role="status">${E(error)}</p>`;}else cards=list.map(card).join('');
  mount(`${progress()}${nav()}<section class="pilot-page-header game-banner game-${pg.key}"><span class="game-icon" aria-hidden="true">${g.icon}</span><div><p class="hard-eyebrow">${T('Seite','Page','Page')} ${a.page+1}/${pages().length}</p><h3>${E(g.name())}</h3><p class="game-rule">${E(g.rule())}</p></div></section>${cards}<p class="hard-error" data-games-notice role="alert">${E(notice)}</p><div class="challenge-actions">${a.page>0?`<button class="secondary-btn" data-games-prev>← ${T('Vorige Seite','Previous page','Page précédente')}</button>`:''}${learnPage&&!checked?'':`<button class="hard-start" ${checked?'data-games-next':'data-games-check'}>${checked?T('Weiter','Next','Suivant'):T('Antworten prüfen','Check answers','Vérifier')} →</button>`}</div>`);
  bindScene();}
 function bindScene(){
  root.querySelectorAll('[data-games-goto]').forEach(el=>el.onclick=()=>goTo(Number(el.dataset.gamesGoto)));
  root.querySelector('[data-games-prev]')?.addEventListener('click',()=>goTo(a.page-1));
  root.querySelector('[data-games-check]')?.addEventListener('click',check);
  root.querySelector('[data-games-next]')?.addEventListener('click',next);
  root.querySelectorAll('[data-games-input]').forEach(el=>{const write=()=>{const i=Number(el.dataset.gamesInput);if(!a.checked[i]){a.answers[i]=el.value;persist();}};el.oninput=write;el.onchange=write;el.addEventListener('focus',()=>{last[el.dataset.gamesInput]=el;});});
  const last={};root.querySelectorAll('[data-games-accent]').forEach(el=>{el.onmousedown=e=>e.preventDefault();el.onclick=()=>{const i=el.dataset.gamesAccent;const input=last[i]||root.querySelector(`[data-games-input="${i}"]`);if(!input||a.checked[Number(i)])return;const s=input.selectionStart??input.value.length,e=input.selectionEnd??s;input.value=input.value.slice(0,s)+el.dataset.char+input.value.slice(e);input.focus();input.setSelectionRange?.(s+1,s+1);input.dispatchEvent(new Event('input',{bubbles:true}));};});
  root.querySelectorAll('[data-games-choice]').forEach(el=>el.onchange=()=>{const i=Number(el.dataset.gamesChoice);if(!a.checked[i]){a.answers[i]=el.value;persist();}});
  root.querySelectorAll('[data-games-token]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.gamesToken),n=Number(el.dataset.token);if(a.checked[i]||a.answers[i].includes(n))return;a.answers[i].push(n);persist();scene();});
  root.querySelectorAll('[data-games-wagon]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.gamesWagon);if(a.checked[i])return;a.answers[i].splice(Number(el.dataset.pos),1);persist();scene();});
  root.querySelectorAll('[data-games-undo]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.gamesUndo);if(a.checked[i])return;a.answers[i].pop();persist();scene();});
  root.querySelectorAll('[data-games-say]').forEach(el=>el.onclick=()=>speak(solution(tasks()[Number(el.dataset.gamesSay)])));
  root.querySelectorAll('[data-games-listen]').forEach(el=>el.onclick=()=>play(Number(el.dataset.gamesListen)));
  root.querySelectorAll('[data-games-stop]').forEach(el=>el.onclick=()=>{cancel();audioState();});
  root.querySelector('[data-games-rate]')?.addEventListener('change',e=>{a.rate=Number(e.target.value);persist();});
  bindMatch();bindMemory();bindRounds();audioState();}

 /* ----- string game ----- */
 function bindMatch(){const palette=['#9fb6ff','#77dec5','#ff9ab1','#f3d38b','#d0a8ff','#ffbd87'];const drawers=[];
  for(const board of root.querySelectorAll('[data-games-connect]')){const i=Number(board.dataset.gamesConnect),q=tasks()[i],left=[...board.querySelectorAll('[data-match-left]')],right=[...board.querySelectorAll('[data-match-right]')],svg=board.querySelector('svg');let selected=null;
   function lines(){if(!board.isConnected)return;const r0=board.getBoundingClientRect();svg.replaceChildren();if(!r0.width)return;svg.setAttribute('viewBox',`0 0 ${r0.width} ${r0.height}`);a.answers[i].forEach((v,n)=>{const k=a.orders[i].indexOf(v);if(!v||k<0)return;const l=left[n].getBoundingClientRect(),r=right[k].getBoundingClientRect(),x1=l.right-r0.left+2,y1=l.top+l.height/2-r0.top,x2=r.left-r0.left-2,y2=r.top+r.height/2-r0.top,mid=(x1+x2)/2;const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',`M ${x1} ${y1} C ${mid} ${y1}, ${mid} ${y2}, ${x2} ${y2}`);path.setAttribute('stroke',palette[n%palette.length]);path.setAttribute('fill','none');svg.append(path);});}
   function update(){left.forEach((b,n)=>{b.classList.toggle('is-selected',selected===n);b.classList.toggle('is-linked',!!a.answers[i][n]);b.style.setProperty('--match-color',palette[n%palette.length]);b.setAttribute('aria-pressed',String(selected===n));});right.forEach((b,n)=>{const owner=a.answers[i].indexOf(a.orders[i][n]);b.classList.toggle('is-linked',owner>=0);b.style.setProperty('--match-color',palette[(owner>=0?owner:0)%palette.length]);});lines();}
   left.forEach((b,n)=>b.onclick=()=>{if(a.checked[i])return;selected=selected===n?null:n;update();});
   right.forEach((b,n)=>b.onclick=()=>{if(a.checked[i]||selected===null)return;const v=a.orders[i][n],remove=a.answers[i][selected]===v;for(let k=0;k<a.answers[i].length;k++)if(a.answers[i][k]===v)a.answers[i][k]='';a.answers[i][selected]=remove?'':v;selected=null;persist();update();});
   update();drawers.push(lines);}
  if(drawers.length){resize=()=>drawers.forEach(d=>d());window.addEventListener('resize',resize);}}

 /* ----- learning games: memory, number safe, spelling box, clock ----- */
 function finishGame(i){a.checked[i]=true;a.solved[i]=true;if(a.firstCorrect[i]===null)a.firstCorrect[i]=true;a.answers[i]=['done'];persist();scene();confetti(root.querySelector(`[data-games-task="${i}"]`),40);}
 function bindMemory(){for(const board of root.querySelectorAll('[data-games-memory]')){const i=Number(board.dataset.gamesMemory),q=tasks()[i],m=a.game[i]||={order:shuffle(Array.from({length:q.pairs.length*2},(_,n)=>n)),open:[],found:[],moves:0};let fresh=[];
  function paint(){if(m.found.length===q.pairs.length){board.innerHTML=`<div class="pilot-memory-results"><h4>✓ ${T('Alle Paare gefunden','All pairs found','Toutes les paires trouvées')}</h4><table><tbody>${q.pairs.map(p=>`<tr><th scope="row" lang="${cfg.target}">${E(p[0])}</th><td>${E(p[1])}</td></tr>`).join('')}</tbody></table></div>`;return;}
   board.innerHTML=`<p class="memory-counter" role="status">${m.found.length}/${q.pairs.length} ${T('Paare gefunden','pairs found','paires trouvées')} · ${m.moves} ${T('Spielzüge','moves','coups')}</p><div class="pilot-memory-grid">${m.order.map(c=>{const pair=Math.floor(c/2),open=m.open.includes(c)||m.found.includes(pair);return `<button type="button" data-memory-card="${c}" class="memory-card ${c%2?'is-form':'is-pronoun'} ${m.found.includes(pair)?'is-found':open?'is-open':''} ${fresh.includes(c)?'is-fresh':''}" style="--pair-hue:${(m.found.indexOf(pair)*47+320)%360}" ${m.found.includes(pair)?'disabled':''} ${c%2?'':`lang="${cfg.target}"`}><span>${open?E(q.pairs[pair][c%2]):'?'}</span></button>`;}).join('')}</div>`;
   board.querySelectorAll('[data-memory-card]').forEach(b=>b.onclick=()=>{const c=Number(b.dataset.memoryCard),pair=Math.floor(c/2);if(m.found.includes(pair)||m.open.includes(c)||m.open.length===2)return;m.open.push(c);fresh=[c];if(m.open.length===2){m.moves++;if(Math.floor(m.open[0]/2)===Math.floor(m.open[1]/2)){m.found.push(pair);fresh=[...m.open];m.open=[];speak(q.pairs[pair][0]);}}persist();if(m.found.length===q.pairs.length)return finishGame(i);paint();});}
  paint();}
  if(root.querySelector('[data-games-memory]')&&!memoryDismiss){memoryDismiss=e=>{if(!root.isConnected)return;for(const board of root.querySelectorAll('[data-games-memory]')){const m=a.game[Number(board.dataset.gamesMemory)];if(m?.open.length===2){e.preventDefault();e.stopImmediatePropagation();m.open=[];persist();scene();return;}}};document.addEventListener('click',memoryDismiss,true);}}
 function clockSvg(h,m){const ha=((h%12)+m/60)*30,ma=m*6,hand=(deg,len,w,c)=>`<line x1="60" y1="60" x2="${60+len*Math.sin(deg*Math.PI/180)}" y2="${60-len*Math.cos(deg*Math.PI/180)}" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
  return `<svg class="games-clock" viewBox="0 0 120 120" role="img" aria-label="${T('Uhr','Clock','Horloge')}"><circle cx="60" cy="60" r="56" fill="#fff8e7" stroke="#ff9f1c" stroke-width="5"/>${Array.from({length:12},(_,k)=>{const d=(k+1)*30*Math.PI/180;return `<text x="${60+44*Math.sin(d)}" y="${64-44*Math.cos(d)}" text-anchor="middle" font-size="11" font-weight="800" fill="#2a1440">${k+1}</text>`;}).join('')}${hand(ha,28,6,'#2a1440')}${hand(ma,42,4,'#ff5d8f')}<circle cx="60" cy="60" r="4" fill="#2a1440"/></svg>`;}
 function bindRounds(){for(const box of root.querySelectorAll('[data-games-rounds]')){const i=Number(box.dataset.gamesRounds),q=tasks()[i],g=a.game[i]||={round:0,input:'',picks:[],wrong:[],hint:false,tries:0};
  const total=q.rounds.length,r=q.rounds[Math.min(g.round,total-1)];
  if(g.round>=total){box.innerHTML=`<div class="pilot-memory-results"><h4>✓ ${T('Alle Runden geschafft','All rounds done','Toutes les manches réussies')}</h4><table><tbody>${q.rounds.map(x=>`<tr><th scope="row">${q.type==='numbers'?x.n:q.type==='spell'?E(x.word):E(`${x.h}:${String(x.m).padStart(2,'0')}`)}</th><td lang="${cfg.target}">${E(q.type==='numbers'?x.word:q.type==='spell'?[...x.word].join(' – '):x.answer)}</td></tr>`).join('')}</tbody></table></div>`;continue;}
  const head=`<p class="memory-counter" role="status">${T('Runde','Round','Manche')} ${g.round+1}/${total}${g.tries?` · ${T('Fehlversuche','misses','erreurs')}: ${g.tries}`:''}</p>`,msg=g.msg?`<p class="games-round-msg ${g.msg==='ok'?'is-ok':'is-wrong'}" role="status">${g.msg==='ok'?'✓ '+cheers[course][g.round%4]:T('Nicht ganz – versuch es noch einmal.','Not quite – try again.','Pas tout à fait – réessaie.')}</p>`:'';
  if(q.type==='numbers')box.innerHTML=`${head}<div class="games-safe ${g.msg==='wrong'?'is-shaking':''}"><div class="games-safe-door"><span class="games-safe-icon" aria-hidden="true">🔐</span><output class="games-safe-display" data-games-display aria-live="polite">${E(g.input)||'· · ·'}</output></div><div class="games-safe-actions"><button type="button" class="secondary-btn" data-games-hear>🔊 ${T('Zahl anhören','Hear the number','Écouter le nombre')}</button><button type="button" class="tiny-btn" data-games-hint>${g.hint?E(r.word):'👀 '+T('Wort zeigen','Show the word','Voir le mot')}</button></div><div class="games-keypad">${[1,2,3,4,5,6,7,8,9,'⌫',0,'✓'].map(k=>`<button type="button" data-games-key="${k}" class="${k==='✓'?'is-enter':k==='⌫'?'is-back':''}" aria-label="${k==='✓'?T('Öffnen','Open','Ouvrir'):k==='⌫'?T('Löschen','Delete','Effacer'):k}">${k}</button>`).join('')}</div></div>${msg}`;
  if(q.type==='spell')box.innerHTML=`${head}<div class="games-spell"><div class="games-spell-actions"><button type="button" class="secondary-btn" data-games-hear>🔊 ${T('Buchstabieren hören','Hear the spelling','Écouter l’épellation')}</button><button type="button" class="tiny-btn" data-games-hint>${g.hint?E([...r.word].join(' – ')):'👀 '+T('Buchstaben zeigen','Show the letters','Voir les lettres')}</button></div><div class="games-spell-slots" aria-live="polite">${Array.from({length:r.word.length},(_,k)=>`<button type="button" class="games-slot ${g.picks[k]!==undefined?'is-filled':''}" data-games-slot="${k}">${g.picks[k]!==undefined?E(r.tiles[g.picks[k]]):''}</button>`).join('')}</div><div class="games-spell-tiles">${r.tiles.map((c,k)=>`<button type="button" class="games-tile" data-games-tile="${k}" style="--hue:${k*53%360}" ${g.picks.includes(k)?'disabled':''}>${E(c)}</button>`).join('')}</div><button type="button" class="hard-start" data-games-spell-check ${g.picks.length===r.word.length?'':'disabled'}>✓ ${T('Prüfen','Check','Vérifier')}</button></div>${msg}`;
  if(q.type==='clock')box.innerHTML=`${head}<div class="games-clock-wrap">${clockSvg(r.h,r.m)}<div class="games-clock-options">${r.options.map((o,k)=>`<button type="button" class="game-quiz-card games-clock-option ${g.wrong.includes(k)?'is-wrong':''}" data-games-time="${k}" style="--hue:${[330,200,45,150][k]}" lang="${cfg.target}" ${g.wrong.includes(k)?'disabled':''}><b class="game-letter" aria-hidden="true">${'ABCD'[k]}</b> ${E(o)}</button>`).join('')}</div></div>${msg}`;
  const advance=()=>{g.round++;g.input='';g.picks=[];g.wrong=[];g.hint=false;g.msg='ok';persist();if(g.round>=total)return finishGame(i);scene();};
  const miss=()=>{g.tries++;g.msg='wrong';persist();scene();};
  box.querySelector('[data-games-hear]')?.addEventListener('click',()=>{if(q.type==='numbers')speak(r.word);else{const letters=[...r.word];if(window.A1Voice?.speakSequence)try{window.A1Voice.speakSequence(letters,{lang:cfg.voice,rate:.7});}catch{}else speak(letters.join(', '));}});
  box.querySelector('[data-games-hint]')?.addEventListener('click',()=>{g.hint=true;a.hints[i]=true;persist();scene();});
  box.querySelectorAll('[data-games-key]').forEach(b=>b.onclick=()=>{const k=b.dataset.gamesKey;g.msg='';if(k==='⌫')g.input=g.input.slice(0,-1);else if(k==='✓'){if(!g.input)return;if(Number(g.input)===r.n)return advance();g.input='';return miss();}else if(g.input.length<3)g.input+=k;persist();box.querySelector('[data-games-display]').textContent=g.input||'· · ·';});
  box.querySelectorAll('[data-games-tile]').forEach(b=>b.onclick=()=>{const k=Number(b.dataset.gamesTile);if(g.picks.includes(k)||g.picks.length>=r.word.length)return;g.picks.push(k);g.msg='';persist();scene();});
  box.querySelectorAll('[data-games-slot]').forEach(b=>b.onclick=()=>{const k=Number(b.dataset.gamesSlot);if(g.picks[k]===undefined)return;g.picks.splice(k,1);persist();scene();});
  box.querySelector('[data-games-spell-check]')?.addEventListener('click',()=>{if(g.picks.map(k=>r.tiles[k]).join('')===r.word)return advance();g.picks=[];miss();});
  box.querySelectorAll('[data-games-time]').forEach(b=>b.onclick=()=>{const k=Number(b.dataset.gamesTime);if(r.options[k]===r.answer){speak(r.answer);return advance();}g.wrong.push(k);miss();});}}

 /* ----- listening ----- */
 function audioState(){root?.querySelectorAll('[data-games-listen]').forEach(b=>{const k=Number(b.dataset.gamesListen);b.disabled=playing!==null||(a.plays[k]||0)>=2;b.textContent=`▶ ${T('Anhören','Listen','Écouter')} (${a.plays[k]||0}/2)`;});root?.querySelectorAll('[data-games-stop]').forEach(s=>s.hidden=playing!==Number(s.dataset.gamesStop));root?.querySelectorAll('.game-radio').forEach(r=>r.classList.toggle('is-playing',playing!==null&&playing===Number(r.dataset.radio)));const el=root?.querySelector('[data-games-audio-error]');if(el)el.textContent=error||(playing!==null?T('Audio läuft …','Audio playing …','Lecture en cours …'):'');}
 function play(b){if(playing!==null||(a.plays[b]||0)>=2)return;const data=cfg.content()[id],helper=cfg.audio();if(!window.A1Voice?.speakDialogue||!helper?.turns){error=T('Audio ist in diesem Browser nicht verfügbar.','Audio is unavailable in this browser.','L’audio n’est pas disponible dans ce navigateur.');audioState();return;}
  const current=++run;let settled=false;a.plays[b]=(a.plays[b]||0)+1;playing=b;error='';persist();audioState();
  const finish=failed=>{if(settled||current!==run)return;settled=true;if(timer)clearTimeout(timer);timer=null;playing=null;if(failed){a.plays[b]=Math.max(0,a.plays[b]-1);error=T('Audio fehlgeschlagen. Dieser Versuch zählt nicht.','Audio failed. This play does not count.','L’audio a échoué. Cette écoute ne compte pas.');persist();}audioState();};
  timer=setTimeout(()=>{finish(true);window.A1Voice?.cancel?.();},240000);
  try{if(window.A1Voice.speakDialogue(helper.turns(id,data,b),{lang:cfg.voice,rate:a.rate,onEnd:()=>finish(false),onError:()=>finish(true)})===false)finish(true);}catch{finish(true);}}

 /* ----- grading and flow ----- */
 function correct(q,i){const v=a.answers[i];if(q.type==='match')return q.answers.every((x,n)=>matches(v[n],[x],q.policy[n]));if(q.type==='order')return matches(v.map(n=>q.tokens[n]).join(' '),[q.answer],{strictAccents:true});if(q.type==='choice')return q.answers.includes(v);return matches(v,q.answers,q.policy||{});}
 function filled(q,i){const v=a.answers[i];if(q.type==='match')return v.every(x=>x);if(q.type==='order')return v.length>0;return !!String(v||'').trim();}
 function check(){const list=visible().filter(i=>scored(i)&&!a.checked[i]);if(list.some(i=>!filled(tasks()[i],i))){notice=T('Bearbeite zuerst alle Aufgaben auf dieser Seite.','Complete all tasks on this page first.','Termine d’abord tous les exercices de cette page.');scene();return;}
  cancel();notice='';for(const i of list){const ok=correct(tasks()[i],i);if(a.firstCorrect[i]===null)a.firstCorrect[i]=ok;a.checked[i]=true;a.solved[i]=ok;}persist();scene();for(const i of list)if(a.solved[i])confetti(root.querySelector(`[data-games-task="${i}"]`));}
 function next(){cancel();notice='';const order=pages().map((_,n)=>n),later=order.find(n=>n>a.page&&pages()[n].ids.some(pending)),open=order.find(n=>pages()[n].ids.some(pending));
  if(later!==undefined||open!==undefined){a.page=later??open;persist();scene();focusTop();return;}
  if(a.solved.every(Boolean)&&!a.completedAt){const s=tasks().map((_,i)=>i).filter(scored),n=s.filter(i=>a.firstCorrect[i]).length;a.phase='reviewed';a.completedAt=Date.now();a.hintsUsed=a.hints.filter(Boolean).length;a.result={correct:n,total:s.length,pct:Math.round(n/Math.max(1,s.length)*100),passed:true};p.arcadeUnlocked=true;persist(true);summary();confetti(root.querySelector('.game-result'),60);}
  else{a.phase=a.completedAt?'reviewed':'summary';persist();summary();}focusTop();}
 function summary(){const s=tasks().map((_,i)=>i).filter(scored),missed=tasks().map((_,i)=>i).filter(i=>!a.solved[i]),n=s.filter(i=>a.firstCorrect[i]).length,share=n/Math.max(1,s.length),stars=share>=.9?3:share>=.7?2:1,won=done(a);
  mount(`${progress()}<section class="card challenge-result game-result ${won?'is-won':''}"><div class="game-trophy" role="img" aria-label="${won?`${stars}/3`:''}"><span class="game-trophy-icon" aria-hidden="true">${won?'🏆':'🎯'}</span>${won?`<span class="game-trophy-stars" aria-hidden="true">${[1,2,3].map(k=>`<i class="${k<=stars?'is-lit':''}">★</i>`).join('')}</span>`:''}</div><span class="challenge-complete">${won?T('✓ HARD MODE GESCHAFFT','✓ HARD MODE COMPLETED','✓ HARD MODE RÉUSSI'):T('RUNDE AUSGEWERTET','ROUND REVIEWED','MANCHE ÉVALUÉE')}</span><h3>${won?T('Stark! Die Spielhalle ist offen.','Great! The arcade is open.','Bravo ! La salle de jeux est ouverte.'):T('Jetzt gezielt nachbessern.','Now improve the difficult parts.','Maintenant, on corrige ce qui manque.')}</h3><p>${n}/${s.length} ${T('beim ersten Prüfen richtig. Hinweise kosten keine Punkte.','right at the first check. Hints cost no points.','justes au premier essai. Les indices ne coûtent pas de points.')}</p>${missed.length?`<button class="hard-start" data-games-retry>${T(`${missed.length} Aufgaben gezielt verbessern`,`Improve ${missed.length} tasks`,`Améliorer ${missed.length} exercices`)} →</button>`:`<button class="secondary-btn" data-games-new>${T('Neue Runde','New round','Nouvelle manche')}</button>`}${arcadeOpen()?`<button type="button" class="arcade-entry" data-games-arcade>🕹️ ${T('Spielhalle freigeschaltet: Action-Spiele','Arcade unlocked: action games','Salle de jeux débloquée : jeux d’action')} →</button>`:''}</section>`);
  root.querySelector('[data-games-retry]')?.addEventListener('click',()=>{a.round++;a.retryIds=missed;a.phase='running';for(const i of missed){const q=tasks()[i];a.checked[i]=false;a.answers[i]=q.type==='match'?q.labels.map(()=>''):q.type==='order'||LEARN.has(q.type)?[]:'';if(LEARN.has(q.type))delete a.game[i];}for(const b of new Set(missed.filter(i=>tasks()[i].block!==undefined).map(i=>tasks()[i].block)))a.plays[b]=0;a.page=pages().findIndex(pg=>pg.ids.some(i=>missed.includes(i)));persist();scene();focusTop();});
  root.querySelector('[data-games-new]')?.addEventListener('click',start);}

 /* ----- arcade ----- */
 function arcade(){const A=window.FR_A1_ARCADE,games=A.lessonGames(courseKey,id),ar=p.arcade;ar.best||={};ar.stars||={};
  if(arcadeView==='hub'){const total=games.reduce((n,g)=>n+(ar.stars[g.id]||0),0);mount(`<section class="arcade-hub" data-arcade-hub><div class="arcade-hub-head"><span class="arcade-hub-icon" aria-hidden="true">🕹️</span><div><p class="hard-eyebrow">${T('SPIELHALLE','ARCADE','SALLE DE JEUX')} · ${T('LEKTION','LESSON','LEÇON')} ${id}</p><h3>${T('Deine Belohnung: Action-Spiele','Your reward: action games','Ta récompense : des jeux d’action')}</h3><p>${T('Mit den Wörtern und Formen dieser Lektion. Bonus-Spiele: deine Hard-Mode-Wertung bleibt unverändert.','With this lesson’s words and forms. Bonus games: your Hard Mode score is not affected.','Avec les mots et les formes de cette leçon. Jeux bonus : ton score Hard Mode ne change pas.')}</p><p class="arcade-total">⭐ ${total}/${games.length*3}</p></div></div><div class="arcade-grid">${games.map(g=>`<button type="button" class="arcade-tile game-${g.theme}" data-arcade-game="${g.id}"><span class="arcade-tile-icon" aria-hidden="true">${g.icon}</span><strong>${E(g.title)}</strong><small>${E(g.tagline)}</small><span class="arcade-tile-stars">${[1,2,3].map(k=>k<=(ar.stars[g.id]||0)?'★':'☆').join('')}</span><span class="arcade-tile-best">${ar.best[g.id]?`🏆 ${ar.best[g.id]}`:T('Noch nicht gespielt','Not played yet','Pas encore joué')}</span></button>`).join('')}</div><button type="button" class="secondary-btn" data-arcade-back>← ${T('Zurück','Back','Retour')}</button></section>`);
   root.querySelectorAll('[data-arcade-game]').forEach(el=>el.onclick=()=>{arcadeView=el.dataset.arcadeGame;draw();focusTop();});root.querySelector('[data-arcade-back]').onclick=()=>{arcadeView=null;draw();focusTop();};return;}
  const gid=arcadeView;mount(`<section class="arcade-host" data-arcade-host></section>`);
  stopGame=A.mount(root.querySelector('[data-arcade-host]'),gid,{course:courseKey,lesson:id,best:ar.best[gid]||0,onEnd:({score,stars})=>{if(score>(ar.best[gid]||0))ar.best[gid]=score;ar.stars[gid]=Math.max(ar.stars[gid]||0,stars);persist();},onExit:()=>{stopGame=null;arcadeView='hub';draw();focusTop();}});}
 function draw(){if(arcadeView&&arcadeOpen())return arcade();if(!a)return intro();if(a.phase==='running')return scene();return summary();}
 redraw=()=>{if(root?.isConnected&&!stopGame)draw();};
 draw();}
window.A1_GAME_HARD={supports,build,entryHtml,render,numberFr,numberDe,timeFr,timeDe,sentencesOf};
})();
